ID = "builder_pattern_retrofit"
LANG = "java"
GOAL = "Refactor Solution.java perquè la classe User passi a usar el patró Builder. Test.java crida al constructor amb molts paràmetres i cal que funcioni amb el Builder."
INITIAL_FILES = {
    "Solution.java": "import java.util.*;\n\npublic class User {\n    private final String name;\n    private final String email;\n    private final int age;\n    private final boolean active;\n    private final List<String> roles;\n\n    public User(String name, String email, int age, boolean active, List<String> roles) {\n        this.name = name;\n        this.email = email;\n        this.age = age;\n        this.active = active;\n        this.roles = roles != null ? new ArrayList<>(roles) : Collections.emptyList();\n    }\n\n    public String getName() { return name; }\n    public String getEmail() { return email; }\n    public int getAge() { return age; }\n    public boolean isActive() { return active; }\n    public List<String> getRoles() { return Collections.unmodifiableList(roles); }\n}",
    "Test.java": "import java.util.*;\n\npublic class Test {\n    public static void main(String[] args) {\n        User u = new User(\"Alice\", \"alice@example.com\", 30, true, Arrays.asList(\"admin\", \"editor\"));\n        if (!u.getName().equals(\"Alice\") || !u.getEmail().equals(\"alice@example.com\") || u.getAge() != 30)\n            throw new RuntimeException(\"fail: basic fields\");\n        if (u.getRoles().size() != 2) throw new RuntimeException(\"fail: roles\");\n        // Builder usage\n        User b = new User.Builder()\n            .name(\"Bob\")\n            .email(\"bob@test.com\")\n            .age(25)\n            .active(true)\n            .roles(Arrays.asList(\"user\"))\n            .build();\n        if (!b.getName().equals(\"Bob\") || b.getRoles().contains(\"admin\"))\n            throw new RuntimeException(\"fail: builder\");\n        System.out.println(\"OK\");\n    }\n}"
}
TEST_FILE = "Test.java"
MAX_TURNS = 8
